import numpy as np
from scipy.optimize import curve_fit

d=np.loadtxt('spectrum.csv', delimiter=',', skiprows=1)
x,y=d[:,0],d[:,1]

def lor(x, amp, x0, gamma, off):
    return amp * gamma**2 / ((x-x0)**2 + gamma**2) + off

def fitwin(lo,hi,guess_x0):
    m=(x>=lo)&(x<=hi)
    xw,yw=x[m],y[m]
    # initial estimates
    ymax=yw.max(); off0=np.percentile(yw,10)
    amp0=max(ymax-off0,1.0); gam0=20.0
    p0=[amp0,guess_x0,gam0,off0]
    bounds=([0,lo,1e-6,-np.inf],[np.inf,hi,np.inf,np.inf])
    try:
        popt,pcov=curve_fit(lor,xw,yw,p0=p0,bounds=bounds,maxfev=100000)
        r=yw-lor(xw,*popt)
        rmse=np.sqrt(np.mean(r*r))
        return popt,rmse
    except Exception as e:
        return None,str(e)

cases={
'D':[(1250,1450,1347),(1275,1425,1347),(1300,1400,1347),(1280,1410,1347)],
'G':[(1500,1700,1579),(1520,1640,1579),(1540,1620,1579),(1550,1610,1579)],
'2D':[(2550,2850,2694),(2600,2800,2694),(2630,2770,2694),(2650,2740,2694)],
}
for name,wins in cases.items():
    print('\n',name)
    for lo,hi,x0 in wins:
        p,rmse=fitwin(lo,hi,x0)
        if p is None:
            print(f'  {lo}-{hi}: FAIL {rmse}')
        else:
            print(f'  {lo}-{hi}: amp={p[0]:.3f} x0={p[1]:.4f} gamma={p[2]:.4f} off={p[3]:.3f} rmse={rmse:.3f}')
